package vn.iotstar.controller; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.GetMapping; import vn.iotstar.repository.*; @Controller @RequiredArgsConstructor public class HomeController{final UserRepository users;final CategoryRepository cats;final ProductRepository products;@GetMapping("/")String home(){return "home";}@GetMapping("/dashboard")String dash(Model m){m.addAttribute("users",users.count());m.addAttribute("categories",cats.count());m.addAttribute("products",products.count());return "dashboard";}}
